sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
    try {
        // Define the URL to be embedded in the iFrame
        const iframeUrl = "$guided_setup.do#/content/2b09b6b0c3579a100ced12f1b40131bf?focus=ca764f12833d92109a4b66d0deaad304&group_focuses=&home_options=intro&scroll_to=&filter=all";
        const instanceUrl = api.data.get_instance_url_1.output.fullUrl ;
        // Ensure the URL is valid
        if (!iframeUrl || typeof iframeUrl !== "string") {
            console.error("Invalid URL for iFrame:", iframeUrl);
            return ""; // Return an empty string for invalid URLs
        }

        // Return the URL string directly (not HTML, for iframe's src binding)
        return instanceUrl + iframeUrl;
    } catch (error) {
        console.error("Error in evaluateProperty:", error);
        return ""; // Return an empty string on error
    }
}
